data.value:
:root { --bg: #f6f1e6; --surface: #ffffff; --ink: #221e18; --muted: #8d8478; --line: #eae1cf; --red: #c93418; --red-deep: #9c2410; --gold: #c8891a; --green: #2f7d50; --blue: #2b5f9e; }
* { margin: 0px; padding: 0px; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { height: 100%; }
body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; background-position-x: ; background-position-y: ; background-repeat: ; background-attachment: ; background-origin: ; background-clip: ; background-color: ; color: var(--ink); background-image: radial-gradient(rgb(230, 220, 198) 1px, transparent 1px); background-size: 22px 22px; }
button { font-family: inherit; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: none; cursor: pointer; color: inherit; }
.topbar { display: flex; align-items: center; justify-content: space-between; padding: 18px 32px; border-bottom: 1px solid var(--line); background: rgba(246, 241, 230, 0.92); position: sticky; top: 0px; z-index: 50; backdrop-filter: blur(6px); }
.brand { display: flex; align-items: baseline; gap: 12px; }
.brand h1 { font-size: 20px; font-weight: 800; letter-spacing: 0.5px; }
.brand h1 em { font-style: normal; color: var(--red); }
.brand span { font-size: 12px; color: var(--muted); letter-spacing: 1px; }
.endswitch { display: flex; background: rgb(236, 228, 210); border-radius: 99px; padding: 3px; gap: 2px; }
.endswitch button { padding: 7px 18px; border-radius: 99px; font-size: 13px; font-weight: 600; color: var(--muted); transition: 0.2s; }
.endswitch button.on { background: var(--ink); color: rgb(255, 255, 255); }
.layout { display: grid; grid-template-columns: 300px 1fr; gap: 0px; max-width: 1280px; margin: 0px auto; padding: 28px 24px 60px; }
.sitemap { padding-right: 28px; }
.sitemap h2 { font-size: 13px; color: var(--muted); font-weight: 600; letter-spacing: 2px; margin: 18px 0px 10px; }
.sitemap h2:first-child { margin-top: 0px; }
.navitem { display: flex; align-items: center; gap: 10px; width: 100%; text-align: left; padding: 11px 12px; border-radius: 10px; font-size: 14px; font-weight: 600; border: 1px solid transparent; transition: 0.15s; margin-bottom: 4px; }
.navitem small { margin-left: auto; font-size: 11px; color: var(--muted); font-weight: 400; }
.navitem:hover { background: rgb(239, 232, 216); }
.navitem.on { background: var(--surface); border-color: var(--line); box-shadow: rgba(60, 45, 20, 0.06) 0px 2px 8px; }
.navitem.on::before { content: ""; width: 6px; height: 6px; border-radius: 99px; background: var(--red); }
.navdesc { margin-top: 22px; padding: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: 12px; }
.navdesc h3 { font-size: 13px; margin-bottom: 6px; }
.navdesc p { font-size: 12px; color: var(--muted); line-height: 1.7; }
.stage { display: flex; justify-content: center; }
.phone { width: 392px; height: 812px; background: rgb(17, 17, 17); border-radius: 52px; padding: 12px; box-shadow: rgba(50, 38, 15, 0.35) 0px 30px 60px -18px, rgb(0, 0, 0) 0px 0px 0px 1px; position: sticky; top: 96px; flex: 0 0 auto; }
.screen-wrap { width: 100%; height: 100%; border-radius: 42px; overflow: hidden; position: relative; background: rgb(244, 239, 227); }
.statusbar { height: 40px; display: flex; align-items: center; justify-content: space-between; padding: 0px 26px; font-size: 13px; font-weight: 700; position: relative; z-index: 20; background: transparent; flex: 0 0 auto; }
.statusbar .sicons { display: flex; gap: 5px; align-items: center; font-size: 11px; }
.screen { position: absolute; inset: 0px; display: none; flex-direction: column; background: rgb(244, 239, 227); }
.screen.on { display: flex; }
.screen .body { flex: 1 1 0%; overflow-y: auto; padding: 0px 16px 90px; scrollbar-width: none; }
.screen .body::-webkit-scrollbar { display: none; }
.navbar { display: flex; align-items: center; justify-content: space-between; padding: 4px 16px 10px; flex: 0 0 auto; }
.navbar .loc { font-size: 15px; font-weight: 700; display: flex; align-items: center; gap: 4px; }
.capsule { display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 99px; padding: 5px 12px; font-size: 12px; color: var(--muted); background: rgb(255, 255, 255); }
.pagetitle { font-size: 19px; font-weight: 800; padding: 6px 16px 12px; flex: 0 0 auto; }
.pagetitle small { font-size: 12px; color: var(--muted); font-weight: 400; margin-left: 8px; }
.card { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; }
.chip { display: inline-block; font-size: 10px; padding: 2px 8px; border-radius: 99px; font-weight: 600; }
.chip.g { background: rgb(231, 242, 234); color: var(--green); }
.chip.y { background: rgb(251, 240, 217); color: var(--gold); }
.chip.r { background: rgb(251, 228, 222); color: var(--red); }
.chip.gray { background: rgb(238, 238, 238); color: var(--muted); }
.btn-red { background: var(--red); color: rgb(255, 255, 255); font-weight: 700; border-radius: 99px; padding: 11px 26px; font-size: 14px; box-shadow: rgba(201, 52, 24, 0.28) 0px 4px 12px; }
.btn-red:active { transform: scale(0.97); }
.divider { height: 1px; background: var(--line); margin: 0px 16px; }
.hero { margin: 6px 0px 14px; border-radius: 20px; overflow: hidden; position: relative; background: linear-gradient(160deg, rgb(185, 44, 18) 0%, rgb(217, 74, 30) 55%, rgb(224, 123, 42) 100%); color: rgb(255, 255, 255); padding: 22px 20px 26px; }
.hero::after { content: ""; position: absolute; right: -30px; top: -30px; width: 150px; height: 150px; border-radius: 50%; background: rgba(255, 255, 255, 0.08); }
.hero::before { content: ""; position: absolute; right: 34px; bottom: -46px; width: 110px; height: 110px; border-radius: 50%; background: rgba(255, 255, 255, 0.07); }
.hero .tag { font-size: 11px; background: rgba(255, 255, 255, 0.2); display: inline-block; padding: 3px 10px; border-radius: 99px; letter-spacing: 1px; }
.hero h2 { font-size: 24px; font-weight: 900; margin: 10px 0px 6px; letter-spacing: 1px; }
.hero p { font-size: 12px; opacity: 0.9; line-height: 1.6; }
.hero .date { margin-top: 12px; font-size: 11px; opacity: 0.85; border-top: 1px dashed rgba(255, 255, 255, 0.35); padding-top: 10px; display: inline-block; }
.points-strip { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; margin-bottom: 14px; }
.points-strip .lab { font-size: 12px; color: var(--muted); }
.points-strip .num { font-size: 26px; font-weight: 900; font-variant-numeric: tabular-nums; line-height: 1.1; }
.points-strip .num i { font-style: normal; font-size: 12px; color: var(--gold); }
.points-strip .go { font-size: 12px; font-weight: 700; color: var(--red); border: 1px solid var(--red); padding: 6px 14px; border-radius: 99px; }
.steps { padding: 16px; margin-bottom: 14px; }
.steps h3, .sect-title { font-size: 15px; font-weight: 800; margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }
.sect-title { margin: 18px 2px 10px; }
.sect-title::before { content: ""; width: 4px; height: 14px; background: var(--red); border-radius: 2px; }
.step-row { display: flex; position: relative; }
.step-row::before { content: ""; position: absolute; top: 19px; left: 12%; right: 12%; height: 2px; background: var(--line); z-index: 0; }
.step { flex: 1 1 0%; text-align: center; position: relative; z-index: 1; }
.step .ic { width: 38px; height: 38px; margin: 0px auto 7px; border-radius: 12px; background: rgb(253, 246, 231); border: 1px solid var(--line); display: flex; align-items: center; justify-content: center; }
.step .ic svg { width: 19px; height: 19px; }
.step p { font-size: 11px; font-weight: 600; }
.step span { font-size: 9px; color: var(--muted); }
.entry-grid { display: grid; grid-template-columns: 1.35fr 1fr; gap: 10px; margin-bottom: 6px; }
.entry { border-radius: 16px; padding: 16px 14px; position: relative; overflow: hidden; text-align: left; border: 1px solid var(--line); background: var(--surface); }
.entry.main { background: rgb(255, 255, 255); border: 1.5px solid var(--red); }
.entry h4 { font-size: 15px; font-weight: 800; margin-bottom: 4px; }
.entry p { font-size: 11px; color: var(--muted); line-height: 1.5; }
.entry .arrow { position: absolute; right: 12px; bottom: 12px; font-size: 11px; font-weight: 700; color: var(--red); }
.entry.side { display: flex; flex-direction: column; gap: 10px; padding: 0px; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; background: none; }
.entry.side .mini { flex: 1 1 0%; background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 12px; text-align: left; }
.entry.side .mini h4 { font-size: 13px; font-weight: 800; }
.entry.side .mini p { font-size: 10px; color: var(--muted); margin-top: 3px; }
.cut-banner { display: flex; align-items: center; justify-content: space-between; background: rgb(34, 30, 24); color: rgb(245, 233, 200); border-radius: 14px; padding: 13px 16px; margin: 10px 0px 4px; }
.cut-banner b { font-size: 14px; }
.cut-banner b i { font-style: normal; color: rgb(255, 176, 58); }
.cut-banner span { font-size: 10px; opacity: 0.7; display: block; margin-top: 2px; }
.cut-banner .pill { font-size: 11px; background: rgb(255, 176, 58); color: rgb(34, 30, 24); font-weight: 800; padding: 5px 12px; border-radius: 99px; }
.scenic-scroll { display: flex; gap: 10px; overflow-x: auto; padding: 2px 2px 8px; scrollbar-width: none; }
.scenic-scroll::-webkit-scrollbar { display: none; }
.scenic { flex: 0 0 128px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }
.scenic .pic { height: 78px; position: relative; }
.scenic .pic svg { width: 100%; height: 100%; display: block; }
.scenic .info { padding: 8px 10px 10px; }
.scenic h5 { font-size: 12px; font-weight: 700; }
.scenic .meta { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); margin-top: 4px; }
.scenic .meta b { color: var(--red); }
.tabbar { position: absolute; bottom: 0px; left: 0px; right: 0px; height: 74px; z-index: 30; background: rgba(255, 255, 255, 0.96); border-top: 1px solid var(--line); display: flex; padding: 8px 6px 20px; backdrop-filter: blur(8px); }
.tabbar .tab { flex: 1 1 0%; display: flex; flex-direction: column; align-items: center; gap: 3px; font-size: 10px; color: var(--muted); font-weight: 600; }
.tabbar .tab svg { width: 22px; height: 22px; }
.tabbar .tab.on { color: var(--red); }
.upload-hero { display: flex; align-items: center; justify-content: space-between; background: rgb(34, 30, 24); color: rgb(255, 255, 255); border-radius: 18px; padding: 18px; margin-bottom: 14px; }
.upload-hero .lab { font-size: 11px; opacity: 0.65; }
.upload-hero .num { font-size: 30px; font-weight: 900; font-variant-numeric: tabular-nums; color: rgb(255, 217, 138); }
.upload-hero a { font-size: 11px; color: rgb(255, 217, 138); text-decoration: underline; text-underline-offset: 3px; }
.dropbox { border: 1.5px dashed rgb(216, 201, 168); border-radius: 18px; background: var(--surface); padding: 26px 18px; text-align: center; margin-bottom: 12px; }
.dropbox .cam { width: 56px; height: 56px; margin: 0px auto 10px; border-radius: 50%; background: rgb(251, 240, 217); display: flex; align-items: center; justify-content: center; }
.dropbox .cam svg { width: 26px; height: 26px; }
.dropbox h4 { font-size: 15px; font-weight: 800; margin-bottom: 4px; }
.dropbox p { font-size: 11px; color: var(--muted); line-height: 1.6; }
.upload-btns { display: flex; gap: 10px; margin-bottom: 16px; }
.upload-btns button { flex: 1 1 0%; padding: 12px; border-radius: 12px; font-size: 13px; font-weight: 700; border: 1px solid var(--line); background: var(--surface); display: flex; align-items: center; justify-content: center; gap: 6px; }
.upload-btns button.primary { background: var(--red); color: rgb(255, 255, 255); border-color: var(--red); }
.upload-btns button svg { width: 16px; height: 16px; }
.inv-list .inv { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.inv-list .inv:last-child { border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; }
.inv-list .ficon { width: 38px; height: 38px; border-radius: 10px; background: rgb(253, 246, 231); border: 1px solid var(--line); display: flex; align-items: center; justify-content: center; flex: 0 0 auto; }
.inv-list .ficon svg { width: 18px; height: 18px; }
.inv-list .fdet { flex: 1 1 0%; min-width: 0px; }
.inv-list .fdet h5 { font-size: 13px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.inv-list .fdet p { font-size: 10px; color: var(--muted); margin-top: 3px; }
.inv-list .fpts { text-align: right; flex: 0 0 auto; }
.inv-list .fpts b { font-size: 15px; color: var(--gold); font-variant-numeric: tabular-nums; }
.inv-list .fpts .chip { margin-top: 3px; }
.pts-hero { text-align: center; padding: 26px 0px 20px; }
.pts-hero .lab { font-size: 12px; color: var(--muted); }
.pts-hero .num { font-size: 46px; font-weight: 900; font-variant-numeric: tabular-nums; line-height: 1.2; }
.pts-hero .num i { font-style: normal; font-size: 16px; color: var(--gold); }
.pts-hero .sub { font-size: 11px; color: var(--muted); margin-top: 6px; }
.pts-hero .sub b { color: var(--red); }
.pts-row { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.pts-row:last-child { border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; }
.pts-row h5 { font-size: 13px; font-weight: 700; }
.pts-row p { font-size: 10px; color: var(--muted); margin-top: 3px; }
.pts-row .amt { font-size: 16px; font-weight: 800; font-variant-numeric: tabular-nums; }
.pts-row .amt.plus { color: var(--gold); }
.pts-row .amt.minus { color: var(--muted); }
.mall-tabs { display: flex; gap: 8px; margin-bottom: 12px; }
.mall-tabs button { padding: 8px 18px; border-radius: 99px; font-size: 13px; font-weight: 700; background: var(--surface); border: 1px solid var(--line); color: var(--muted); }
.mall-tabs button.on { background: var(--ink); color: rgb(255, 255, 255); border-color: var(--ink); }
.ticket { display: flex; background: var(--surface); border: 1px solid var(--line); border-radius: 16px; overflow: hidden; margin-bottom: 12px; position: relative; }
.ticket .stub { flex: 0 0 96px; background: rgb(253, 246, 231); border-right: 2px dashed var(--line); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; padding: 12px 6px; position: relative; }
.ticket .stub::before, .ticket .stub::after { content: ""; position: absolute; right: -8px; width: 14px; height: 14px; border-radius: 50%; background: rgb(244, 239, 227); border: 1px solid var(--line); }
.ticket .stub::before { top: -8px; }
.ticket .stub::after { bottom: -8px; }
.ticket .stub .p { font-size: 18px; font-weight: 900; color: var(--red); font-variant-numeric: tabular-nums; }
.ticket .stub .p i { font-style: normal; font-size: 10px; }
.ticket .stub .o { font-size: 10px; color: var(--muted); text-decoration: line-through; }
.ticket .tmain { flex: 1 1 0%; padding: 13px 14px; min-width: 0px; }
.ticket .tmain h5 { font-size: 14px; font-weight: 800; }
.ticket .tmain p { font-size: 10px; color: var(--muted); margin: 5px 0px 9px; line-height: 1.5; }
.ticket .tmain .row { display: flex; align-items: center; justify-content: space-between; }
.ticket .tmain .row .stock { font-size: 10px; color: var(--gold); }
.ticket .exbtn { background: var(--red); color: rgb(255, 255, 255); font-size: 12px; font-weight: 700; padding: 7px 16px; border-radius: 99px; }
.ticket .exbtn.dis { background: rgb(216, 210, 196); color: rgb(154, 147, 138); }
.qr-ticket { background: var(--surface); border: 1px solid var(--line); border-radius: 18px; overflow: hidden; margin-bottom: 14px; }
.qr-ticket .head { background: linear-gradient(135deg, rgb(185, 44, 18), rgb(217, 74, 30)); color: rgb(255, 255, 255); padding: 14px 16px; display: flex; justify-content: space-between; align-items: center; }
.qr-ticket .head h5 { font-size: 15px; font-weight: 800; }
.qr-ticket .head span { font-size: 10px; opacity: 0.85; }
.qr-ticket .qrzone { display: flex; align-items: center; gap: 16px; padding: 18px 16px; background-image: radial-gradient(circle at 0px 50%, rgb(244, 239, 227) 8px, transparent 8px), radial-gradient(circle at 100% 50%, rgb(244, 239, 227) 8px, transparent 8px); }
.qr-ticket canvas { width: 92px; height: 92px; flex: 0 0 auto; border: 4px solid rgb(255, 255, 255); box-shadow: 0 0 0 1px var(--line); }
.qr-ticket .qinfo { flex: 1 1 0%; }
.qr-ticket .qinfo p { font-size: 11px; color: var(--muted); line-height: 1.8; }
.qr-ticket .qinfo b { color: var(--ink); }
.qr-ticket .foot { border-top: 1px dashed var(--line); padding: 10px 16px; display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); }
.coupon-mini { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.coupon-mini:last-child { border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; }
.coupon-mini .val { flex: 0 0 74px; text-align: center; border-right: 1px dashed var(--line); padding-right: 12px; }
.coupon-mini .val b { font-size: 22px; color: var(--red); font-variant-numeric: tabular-nums; }
.coupon-mini .val b i { font-style: normal; font-size: 11px; }
.coupon-mini .val p { font-size: 9px; color: var(--muted); }
.coupon-mini .cdet { flex: 1 1 0%; }
.coupon-mini .cdet h5 { font-size: 13px; font-weight: 700; }
.coupon-mini .cdet p { font-size: 10px; color: var(--muted); margin-top: 3px; }
.coupon-mini.used { opacity: 0.45; filter: grayscale(0.6); }
.lotto-wrap { padding: 6px 0px 4px; }
.lotto-times { text-align: center; font-size: 12px; color: var(--muted); margin-bottom: 14px; }
.lotto-times b { color: var(--red); font-size: 16px; }
.lotto-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; background: rgb(232, 220, 194); border-radius: 20px; padding: 10px; }
.lotto-cell { aspect-ratio: 1 / 1; background: var(--surface); border-radius: 12px; border: 2px solid transparent; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; font-size: 11px; font-weight: 700; transition: 0.1s; }
.lotto-cell svg { width: 26px; height: 26px; }
.lotto-cell span { font-size: 9px; color: var(--muted); font-weight: 400; }
.lotto-cell.lit { border-color: var(--red); background: rgb(255, 243, 238); box-shadow: rgba(201, 52, 24, 0.18) 0px 0px 0px 3px; }
.lotto-btn { color: rgb(255, 255, 255); border-radius: 12px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px; box-shadow: rgb(143, 34, 16) 0px 4px 0px; background: linear-gradient(rgb(224, 90, 36), rgb(201, 52, 24)) !important; }
.lotto-btn b { font-size: 17px; font-weight: 900; }
.lotto-btn span { font-size: 9px; opacity: 0.85; color: rgb(255, 255, 255) !important; }
.lotto-btn:active { transform: translateY(2px); box-shadow: rgb(143, 34, 16) 0px 2px 0px; }
.lotto-note { margin-top: 14px; padding: 14px 16px; font-size: 11px; color: var(--muted); line-height: 1.8; }
.me-card { display: flex; align-items: center; gap: 14px; padding: 18px 16px; margin-bottom: 12px; }
.me-card .avatar { width: 56px; height: 56px; border-radius: 50%; background: linear-gradient(135deg, rgb(224, 161, 58), rgb(201, 52, 24)); display: flex; align-items: center; justify-content: center; color: rgb(255, 255, 255); font-size: 22px; font-weight: 800; flex: 0 0 auto; }
.me-card h4 { font-size: 16px; font-weight: 800; display: flex; align-items: center; gap: 6px; }
.me-card p { font-size: 11px; color: var(--muted); margin-top: 4px; }
.me-stats { display: flex; text-align: center; padding: 12px 0px; margin-bottom: 12px; }
.me-stats div { flex: 1 1 0%; border-right: 1px solid var(--line); }
.me-stats div:last-child { border-right-width: medium; border-right-style: none; border-right-color: currentcolor; }
.me-stats b { font-size: 19px; font-variant-numeric: tabular-nums; }
.me-stats p { font-size: 10px; color: var(--muted); margin-top: 3px; }
.menu .mrow { display: flex; align-items: center; gap: 12px; padding: 15px 16px; border-bottom: 1px solid var(--line); font-size: 14px; font-weight: 600; width: 100%; text-align: left; }
.menu .mrow:last-child { border-bottom-width: medium; border-bottom-style: none; border-bottom-color: currentcolor; }
.menu .mrow svg { width: 18px; height: 18px; flex: 0 0 auto; }
.menu .mrow .rt { margin-left: auto; color: rgb(201, 192, 176); font-size: 16px; }
.rules h4 { font-size: 14px; font-weight: 800; margin: 16px 2px 8px; }
.rules p, .rules li { font-size: 12px; color: rgb(93, 86, 76); line-height: 1.9; }
.rules ol { padding-left: 18px; }
.rules .hl { background: rgb(253, 246, 231); border-left: 3px solid var(--gold); padding: 10px 12px; border-radius: 0px 8px 8px 0px; margin: 10px 0px; font-size: 11px; }
.m-hero { background: rgb(34, 30, 24); color: rgb(255, 255, 255); border-radius: 18px; padding: 18px; margin-bottom: 14px; }
.m-hero .shop { font-size: 13px; opacity: 0.75; }
.m-hero h3 { font-size: 18px; font-weight: 800; margin-top: 4px; }
.m-kpi { display: flex; gap: 10px; margin-bottom: 14px; }
.m-kpi .k { flex: 1 1 0%; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 14px; text-align: center; }
.m-kpi .k b { font-size: 22px; font-variant-numeric: tabular-nums; display: block; }
